import{useInfiniteQuery as tanstack_useInfiniteQuery,useQuery as tanstack_useQuery,useMutation}from"@tanstack/react-query";import{hashFn}from"@wagmi/core/query";export{useMutation};export function useQuery(parameters){const result=tanstack_useQuery({...parameters,queryKeyHashFn:hashFn});return result.queryKey=parameters.queryKey,result}export function useInfiniteQuery(parameters){const result=tanstack_useInfiniteQuery({...parameters,queryKeyHashFn:hashFn});return result.queryKey=parameters.queryKey,result}