import{protoInt64}from"../proto-int64.js";import{LongType,ScalarType}from"../scalar.js";export function scalarEquals(type,a,b){if(a===b)return!0;if(type==ScalarType.BYTES){if(!(a instanceof Uint8Array&&b instanceof Uint8Array))return!1;if(a.length!==b.length)return!1;for(let i=0;i<a.length;i++)if(a[i]!==b[i])return!1;return!0}switch(type){case ScalarType.UINT64:case ScalarType.FIXED64:case ScalarType.INT64:case ScalarType.SFIXED64:case ScalarType.SINT64:return a==b}return!1}export function scalarZeroValue(type,longType){switch(type){case ScalarType.BOOL:return!1;case ScalarType.UINT64:case ScalarType.FIXED64:case ScalarType.INT64:case ScalarType.SFIXED64:case ScalarType.SINT64:return 0==longType?protoInt64.zero:"0";case ScalarType.DOUBLE:case ScalarType.FLOAT:return 0;case ScalarType.BYTES:return new Uint8Array(0);case ScalarType.STRING:return"";default:return 0}}export function isScalarZeroValue(type,value){switch(type){case ScalarType.BOOL:return!1===value;case ScalarType.STRING:return""===value;case ScalarType.BYTES:return value instanceof Uint8Array&&!value.byteLength;default:return 0==value}}