import{useMutation}from"@tanstack/react-query";import{sendCallsMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useSendCalls(parameters={}){const{mutation:mutation}=parameters,config=useConfig(parameters),mutationOptions=sendCallsMutationOptions(config),{mutate:mutate,mutateAsync:mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,sendCalls:mutate,sendCallsAsync:mutateAsync}}