import{useMutation}from"@tanstack/react-query";import{signTypedDataMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useSignTypedData(parameters={}){const{mutation:mutation}=parameters,config=useConfig(parameters),mutationOptions=signTypedDataMutationOptions(config),{mutate:mutate,mutateAsync:mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,signTypedData:mutate,signTypedDataAsync:mutateAsync}}