import{useMutation}from"@tanstack/react-query";import{deployContractMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useDeployContract(parameters={}){const{mutation:mutation}=parameters,config=useConfig(parameters),mutationOptions=deployContractMutationOptions(config),{mutate:mutate,mutateAsync:mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,deployContract:mutate,deployContractAsync:mutateAsync}}