import{getCapabilities as viem_getCapabilities}from"viem/actions";import{getConnectorClient}from"./getConnectorClient.js";export async function getCapabilities(config,parameters={}){const{account:account,chainId:chainId,connector:connector}=parameters,client=await getConnectorClient(config,{account:account,connector:connector});return viem_getCapabilities(client,{account:account,chainId:chainId})}