import{assert}from"./assert.js";const enumTypeSymbol=Symbol("@bufbuild/protobuf/enum-type");export function getEnumType(enumObject){const t=enumObject[enumTypeSymbol];return assert(t,"missing enum type on enum object"),t}export function setEnumType(enumObject,typeName,values,opt){enumObject[enumTypeSymbol]=makeEnumType(typeName,values.map((v=>({no:v.no,name:v.name,localName:enumObject[v.no]}))),opt)}export function makeEnumType(typeName,values,_opt){const names=Object.create(null),numbers=Object.create(null),normalValues=[];for(const value of values){const n=normalizeEnumValue(value);normalValues.push(n),names[value.name]=n,numbers[value.no]=n}return{typeName:typeName,values:normalValues,findName:name=>names[name],findNumber:no=>numbers[no]}}export function makeEnum(typeName,values,opt){const enumObject={};for(const value of values){const n=normalizeEnumValue(value);enumObject[n.localName]=n.no,enumObject[n.no]=n.localName}return setEnumType(enumObject,typeName,values,opt),enumObject}function normalizeEnumValue(value){return"localName"in value?value:Object.assign(Object.assign({},value),{localName:value.name})}