import{SignatureTransfer}from"@uniswap/permit2-sdk";import{BigNumber,ethers}from"ethers";import{keccak256,toUtf8Bytes}from"ethers/lib/utils";import{BPS,PERMIT2_MAPPING}from"../constants";import{MissingConfiguration}from"../errors";import{getDecayedAmount}from"../utils/dutchDecay";import{parseValidation}from"./validation";export function id(text){return keccak256(toUtf8Bytes(text))}const STRICT_EXCLUSIVITY=BigNumber.from(0),DUTCH_ORDER_TYPES={ExclusiveDutchOrder:[{name:"info",type:"OrderInfo"},{name:"decayStartTime",type:"uint256"},{name:"decayEndTime",type:"uint256"},{name:"exclusiveFiller",type:"address"},{name:"exclusivityOverrideBps",type:"uint256"},{name:"inputToken",type:"address"},{name:"inputStartAmount",type:"uint256"},{name:"inputEndAmount",type:"uint256"},{name:"outputs",type:"DutchOutput[]"}],OrderInfo:[{name:"reactor",type:"address"},{name:"swapper",type:"address"},{name:"nonce",type:"uint256"},{name:"deadline",type:"uint256"},{name:"additionalValidationContract",type:"address"},{name:"additionalValidationData",type:"bytes"}],DutchOutput:[{name:"token",type:"address"},{name:"startAmount",type:"uint256"},{name:"endAmount",type:"uint256"},{name:"recipient",type:"address"}]},DUTCH_ORDER_ABI=["tuple("+["tuple(address,address,uint256,uint256,address,bytes)","uint256","uint256","address","uint256","tuple(address,uint256,uint256)","tuple(address,uint256,uint256,address)[]"].join(",")+")"];export class DutchOrder{constructor(info,chainId,_permit2Address){if(this.info=info,this.chainId=chainId,this._permit2Address=_permit2Address,_permit2Address)this.permit2Address=_permit2Address;else{if(!PERMIT2_MAPPING[chainId])throw new MissingConfiguration("permit2",chainId.toString());this.permit2Address=PERMIT2_MAPPING[chainId]}}static fromJSON(json,chainId,_permit2Address){return new DutchOrder(Object.assign(Object.assign({},json),{exclusivityOverrideBps:BigNumber.from(json.exclusivityOverrideBps),nonce:BigNumber.from(json.nonce),input:{token:json.input.token,startAmount:BigNumber.from(json.input.startAmount),endAmount:BigNumber.from(json.input.endAmount)},outputs:json.outputs.map((output=>({token:output.token,startAmount:BigNumber.from(output.startAmount),endAmount:BigNumber.from(output.endAmount),recipient:output.recipient})))}),chainId,_permit2Address)}static parse(encoded,chainId,permit2){const decoded=(new ethers.utils.AbiCoder).decode(DUTCH_ORDER_ABI,encoded),[[[reactor,swapper,nonce,deadline,additionalValidationContract,additionalValidationData],decayStartTime,decayEndTime,exclusiveFiller,exclusivityOverrideBps,[inputToken,inputStartAmount,inputEndAmount],outputs]]=decoded;return new DutchOrder({reactor:reactor,swapper:swapper,nonce:nonce,deadline:deadline.toNumber(),additionalValidationContract:additionalValidationContract,additionalValidationData:additionalValidationData,decayStartTime:decayStartTime.toNumber(),decayEndTime:decayEndTime.toNumber(),exclusiveFiller:exclusiveFiller,exclusivityOverrideBps:exclusivityOverrideBps,input:{token:inputToken,startAmount:inputStartAmount,endAmount:inputEndAmount},outputs:outputs.map((([token,startAmount,endAmount,recipient])=>({token:token,startAmount:startAmount,endAmount:endAmount,recipient:recipient})))},chainId,permit2)}toJSON(){return{chainId:this.chainId,permit2Address:this.permit2Address,reactor:this.info.reactor,swapper:this.info.swapper,nonce:this.info.nonce.toString(),deadline:this.info.deadline,additionalValidationContract:this.info.additionalValidationContract,additionalValidationData:this.info.additionalValidationData,decayStartTime:this.info.decayStartTime,decayEndTime:this.info.decayEndTime,exclusiveFiller:this.info.exclusiveFiller,exclusivityOverrideBps:this.info.exclusivityOverrideBps.toString(),input:{token:this.info.input.token,startAmount:this.info.input.startAmount.toString(),endAmount:this.info.input.endAmount.toString()},outputs:this.info.outputs.map((output=>({token:output.token,startAmount:output.startAmount.toString(),endAmount:output.endAmount.toString(),recipient:output.recipient})))}}get blockOverrides(){}serialize(){return(new ethers.utils.AbiCoder).encode(DUTCH_ORDER_ABI,[[[this.info.reactor,this.info.swapper,this.info.nonce,this.info.deadline,this.info.additionalValidationContract,this.info.additionalValidationData],this.info.decayStartTime,this.info.decayEndTime,this.info.exclusiveFiller,this.info.exclusivityOverrideBps,[this.info.input.token,this.info.input.startAmount,this.info.input.endAmount],this.info.outputs.map((output=>[output.token,output.startAmount,output.endAmount,output.recipient]))]])}getSigner(signature){return ethers.utils.computeAddress(ethers.utils.recoverPublicKey(SignatureTransfer.hash(this.toPermit(),this.permit2Address,this.chainId,this.witness()),signature))}permitData(){return SignatureTransfer.getPermitData(this.toPermit(),this.permit2Address,this.chainId,this.witness())}hash(){return ethers.utils._TypedDataEncoder.from(DUTCH_ORDER_TYPES).hash(this.witnessInfo())}resolve(options){const useOverride=this.info.exclusiveFiller!==ethers.constants.AddressZero&&options.timestamp<=this.info.decayStartTime&&options.filler!==this.info.exclusiveFiller;return{input:{token:this.info.input.token,amount:getDecayedAmount({decayStartTime:this.info.decayStartTime,decayEndTime:this.info.decayEndTime,startAmount:this.info.input.startAmount,endAmount:this.info.input.endAmount},options.timestamp)},outputs:this.info.outputs.map((output=>{const baseAmount=getDecayedAmount({decayStartTime:this.info.decayStartTime,decayEndTime:this.info.decayEndTime,startAmount:output.startAmount,endAmount:output.endAmount},options.timestamp);let amount=baseAmount;return useOverride&&(amount=this.info.exclusivityOverrideBps.eq(STRICT_EXCLUSIVITY)?ethers.constants.MaxUint256:baseAmount.mul(this.info.exclusivityOverrideBps.add(BPS)).div(BPS)),{token:output.token,amount:amount}}))}}get validation(){return parseValidation(this.info)}toPermit(){return{permitted:{token:this.info.input.token,amount:this.info.input.endAmount},spender:this.info.reactor,nonce:this.info.nonce,deadline:this.info.deadline}}witnessInfo(){return{info:{reactor:this.info.reactor,swapper:this.info.swapper,nonce:this.info.nonce,deadline:this.info.deadline,additionalValidationContract:this.info.additionalValidationContract,additionalValidationData:this.info.additionalValidationData},decayStartTime:this.info.decayStartTime,decayEndTime:this.info.decayEndTime,exclusiveFiller:this.info.exclusiveFiller,exclusivityOverrideBps:this.info.exclusivityOverrideBps,inputToken:this.info.input.token,inputStartAmount:this.info.input.startAmount,inputEndAmount:this.info.input.endAmount,outputs:this.info.outputs}}witness(){return{witness:this.witnessInfo(),witnessTypeName:"ExclusiveDutchOrder",witnessType:DUTCH_ORDER_TYPES}}}