import{useMutation}from"@tanstack/react-query";import{reconnectMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useReconnect(parameters={}){const{mutation:mutation}=parameters,config=useConfig(parameters),mutationOptions=reconnectMutationOptions(config),{mutate:mutate,mutateAsync:mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,connectors:config.connectors,reconnect:mutate,reconnectAsync:mutateAsync}}